// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// learn from "Generative Design with p5.js"

var shape;
var seed = Math.random() * 1341;
var joints;
var lineLength;
var speedRelation;
var mySize;

var showPendulum = 6;
var showPendulumPath = 6;
var rect_ang = 0;

const palettes = [
	["#4596c7", "#6d8370", "#e45240", "#21d3a4", "#3303f9"],
	["#b8dbcc", "#472433", "#e1fff6", "#e3b0c8", "#212523"],
	["#ffffff", "#292929", "#000000", "#f7fcfe", "#14001a"],
	["#5d565c", "#b41a1d", "#c0dee4", "#edb136", "#e07958"],
	["#add8e6", "#9fb7f4", "#12177d", "#9bb5e9", "#e4f2f7"],
	["#1b1b1b", "#292929", "#f3f3f3", "#222222", "#ff0000"],
	["#eda492", "#d59c95", "#af3918", "#d9b6b5", "#853532"],
	["#f86fcd", "#97d183", "#240ce8", "#b0e298", "#7f37e8"],
	["#2E294E", "#541388", "#F1E9DA", "#FFD400", "#D90368"],
	["#e9baaa", "#ffa07a", "#164555", "#ffe1d0", "#acd9e7"]
]
var chosen_ColorNum;

function setup() {
	// pixelDensity(5);
	randomSeed(seed);
	createCanvas(windowWidth, windowHeight);
	mySize = max(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	noFill();
	joints = random([3,4,5,6,8]);
	lineLength = mySize/7;
	speedRelation = random([2,3,4,5,6]);
	chosen_ColorNum = random([0, 1, 2, 3, 4, 5, 6, 7, 8]);
	strokeWeight(random(5));
	startDrawing();
	background(245);
}

function draw() {
	randomSeed(seed);
	// background(245);
	push();
	translate(width / 2, height / 2);
	for (let i = 0; i < 2; i++) {
		rotate(TAU / 2 * i);
		shape.draw();
	}
	pop();
}

function startDrawing() {
	shape = new Shape(0, 0, joints, lineLength, speedRelation);
}

function Shape(x, y, joints, lineLength, speedRelation, speed) {

	this.center = createVector(x, y);
	this.pendulumPath = [];
	this.angle = 0;
	this.maxAngle = 360;
	this.joints = joints;
	this.lineLength = lineLength;
	this.speedRelation = speedRelation || 2;
	this.speed = speed || (random([4,6,8,10,12]) / pow(1.75, this.joints - 1) / pow(2, speedRelation - 1));

	// new empty array for each joint
	for (var i = 0; i < this.joints; i++) {
		this.pendulumPath.push([]);
	}

	Shape.prototype.draw = function() {
		this.angle += this.speed;
		randomSeed(seed);
		if (this.angle <= this.maxAngle + this.speed) {
			// start at the center position
			var pos = this.center.copy();

			for (var i = 0; i < this.joints; i++) {
				var a = this.angle * pow(speedRelation, i);
				if (i % 2 == 1) a = -a;

				var nextPos = p5.Vector.fromAngle(radians(a));

				nextPos.setMag((this.lineLength / this.joints) * (this.joints - i));
				nextPos.add(pos);

				pos = nextPos;

				this.pendulumPath[i].push(pos);
			}
		}else{noLoop();}

		drawingContext.shadowColor = random(palettes[chosen_ColorNum]);
		drawingContext.shadowOffsetX = 1;
		drawingContext.shadowOffsetY = 1;
		drawingContext.shadowBlur = 0;
		if (showPendulumPath) {
			strokeWeight(random(1));
			for (let i = 0; i < this.pendulumPath.length; i++) {
				var path = this.pendulumPath[i];
				stroke(random(palettes[chosen_ColorNum]));
				for (var j = 0; j < path.length; j++) {
					push();
					translate(path[j].x, path[j].y);
					// rotate(rect_ang)
					rectMode(CENTER);
					circle(0,0,2);
					pop();
				}
				// rect_ang += TAU / 3600;

			}
		}

	};

}

function keyPressed() {
	if (key == 's' || key == 'S')
		saveCanvas("Union_20220210", 'png');

}

